inputs = ['kg', 'kb', 'huv', 'uf', 'zafe']
outputs = ['kg', 'kb', 'hwchgz', 'wcf', 'zafcvzw']

# Manually analyze differences
print("Analyzing transformations:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"{inp} -> {outp}")
        # Show character by character differences
        print(f"  Lengths: {len(inp)} -> {len(outp)}")

        # Find where they differ
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break

        if diff_pos == -1:
            # One string is prefix of other
            if len(inp) < len(outp):
                print(f"  Append: '{outp[len(inp):]}'")
            else:
                print(f"  Remove: '{inp[len(outp):]}'")
        else:
            print(f"  First difference at position {diff_pos}")

        print()

